package gui;import data.DataStore;import model.User;import service.CalorieCalculator;import javax.swing.*;import javax.swing.border.EmptyBorder;import java.awt.*;
public class WaterTrackerPanel extends Theme.BackgroundPanel{private final MainApp app;private final JLabel value=Theme.title("0.0 L");private final JProgressBar bar=new JProgressBar();public WaterTrackerPanel(MainApp a){app=a;setOpaque(false);setLayout(new BorderLayout(15,15));setBorder(new EmptyBorder(22,28,20,28));add(Theme.title("HYDRATION CENTER 💧"),BorderLayout.NORTH);JPanel p=Theme.cardPanel(new GridLayout(0,1,12,12));p.add(value);p.add(Theme.subtitle("Hydration target is estimated from body weight (33 ml/kg)."));bar.setStringPainted(true);p.add(bar);JPanel b=new JPanel(new FlowLayout());b.setBackground(Theme.CARD_BG);for(int ml:new int[]{250,500,750}){JButton x=Theme.primaryButton("+"+ml+" ml");x.addActionListener(e->{DataStore.addWater(app.getCurrentUser().getUserId(),ml);refresh();});b.add(x);}JButton r=Theme.secondaryButton("Reset today");r.addActionListener(e->{DataStore.resetWater(app.getCurrentUser().getUserId());refresh();});b.add(r);p.add(b);add(p,BorderLayout.CENTER);JButton home=Theme.primaryButton("⌂ HOME");home.addActionListener(e->app.showPanel(MainApp.HOME));JPanel nav=Theme.transparentPanel(new FlowLayout(FlowLayout.RIGHT)); nav.add(home); add(nav,BorderLayout.SOUTH);}public void refresh(){User u=app.getCurrentUser();if(u==null)return;double target=CalorieCalculator.calculateWaterIntakeLitres(u.getWeight()),c=DataStore.getWaterConsumed(u.getUserId())/1000.0;value.setText(String.format("%.1f / %.1f L",c,target));bar.setMaximum((int)(target*1000));bar.setValue(Math.min(DataStore.getWaterConsumed(u.getUserId()),bar.getMaximum()));bar.setString(String.format("%.0f%%",Math.min(100,c/target*100)));}}
